<template><Layout><div class="breadcrumb"><Link :href="route('selling-products.index')">Products</Link><span>›</span>{{ product.name }}</div><div class="page-header product-detail-header"><div><div class="eyebrow">PRODUCT DETAILS</div><h1>{{ product.name }}</h1><p>Listed {{ formatDate(product.created_at) }}</p></div><button class="delete-button" :disabled="deleting" @click="remove">{{ deleting?'Deleting…':'Delete product' }}</button></div><section class="product-detail-grid"><div class="product-detail-main"><article class="detail-card product-gallery"><div class="gallery-main"><img v-if="selectedImage" :src="selectedImage"/><span v-else>No image available</span></div><div v-if="product.images.length>1" class="gallery-thumbs"><button v-for="image in product.images" :key="image.id" :class="{active:selectedImage===image.url}" @click="selectedImage=image.url"><img :src="image.url"/></button></div></article><article class="detail-card"><header><h2>Product information</h2></header><div class="product-title-row"><div><span>{{ product.main_category||'Uncategorised' }} / {{ product.category?.name||'Uncategorised' }}</span><h2>{{ product.name }}</h2></div><strong>{{ money(product.price) }}</strong></div><p class="product-description">{{ product.description||'No description was provided for this product.' }}</p><div class="info-grid product-info"><div><span>Condition</span><strong>{{ readable(product.condition) }}</strong></div><div><span>Available quantity</span><strong>{{ product.quantity }}</strong></div><div><span>Product status</span><strong>{{ readable(product.status) }}</strong></div><div><span>Visibility</span><strong>{{ product.is_active?'Active':'Inactive' }}</strong></div><div><span>Orders</span><strong>{{ product.orders_count }}</strong></div><div><span>Payment methods</span><strong>{{ product.payment_methods.length }}</strong></div></div></article><article v-if="product.video" class="detail-card"><header><h2>Product video</h2></header><video class="product-video" :src="product.video" controls></video></article></div><aside class="product-detail-side"><article class="detail-card person-card"><header><h2>Seller</h2></header><div class="person-heading"><span>{{ initial(product.seller_details?.name) }}</span><div><strong>{{ product.seller_details?.name||'Deleted seller' }}</strong><small :class="{verified:product.seller_details?.is_approved}">{{ product.seller_details?.is_approved?'Verified seller':'Unverified seller' }}</small></div></div><div class="person-lines"><p><span>Phone</span><b>{{ product.seller_details?.phone||'—' }}</b></p><p><span>Email</span><b>{{ product.seller_details?.email||'—' }}</b></p></div><Link v-if="product.seller_details?.id" :href="route('users.show',product.seller_details.id)" class="panel-link">View seller <span>→</span></Link></article><article class="detail-card"><header><h2>Accepted payments</h2></header><div v-if="product.payment_methods.length" class="payment-chips"><span v-for="payment in product.payment_methods" :key="payment.id">{{ payment.name }}</span></div><p v-else class="muted-copy">No payment methods linked.</p></article><article class="detail-card danger-card"><header><h2>Delete listing</h2></header><p>Deleting removes its images, video, payment associations and {{ product.orders_count }} associated orders. This cannot be undone.</p><button class="delete-button" @click="remove">Delete product permanently</button></article></aside></section></Layout></template>
<script setup>import{ref}from'vue';import{router}from'@inertiajs/vue3';import{route}from'ziggy-js';import Layout from'../Layouts/Layout.vue';const props=defineProps({product:Object}),selectedImage=ref(props.product.cover),deleting=ref(false);const money=v=>new Intl.NumberFormat('en-US').format(v)+' Ks',readable=s=>(s||'—').replaceAll('-',' ').replace(/\b\w/g,l=>l.toUpperCase()),initial=n=>(n||'?').charAt(0).toUpperCase(),formatDate=d=>new Intl.DateTimeFormat('en',{dateStyle:'long'}).format(new Date(d));const remove=()=>{if(!window.confirm(`Permanently delete “${props.product.name}”? Its media and ${props.product.orders_count} related orders will also be deleted.`))return;deleting.value=true;router.delete(route('selling-products.destroy',props.product.id),{onFinish:()=>deleting.value=false})};</script>
